'use strict';
const fs = require('fs');
const crypto = require('crypto');
const bytes = fs.readFileSync('app.json');
const value = JSON.parse(bytes).state;
if (!['ready', 'done'].includes(value)) throw new Error('invalid state');
console.log('AGENTSMD_QA_VERIFY:' + JSON.stringify({ value, sha256: crypto.createHash('sha256').update(bytes).digest('hex') }));

